from __future__ import annotations

import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


class Handler(BaseHTTPRequestHandler):
    def do_POST(self) -> None:  # noqa: N802
        length = int(self.headers.get("Content-Length", "0"))
        self.rfile.read(length)
        content = {
            "bonds": [
                {
                    "title": "Explicit browser alliance",
                    "summary": "A public candidate relationship generated by the local live provider.",
                    "source_entity_name": "Character 0001",
                    "target_entity_name": "Alias Character",
                    "relationship_type": "allies",
                }
            ],
            "plot_threads": [],
            "conflict_triggers": [],
        }
        payload = json.dumps({"choices": [{"message": {"content": json.dumps(content)}}]}).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def log_message(self, _format: str, *_args: object) -> None:
        return


if __name__ == "__main__":
    address = os.environ.get("MIROFISH_GRAPH_PROVIDER_ADDR", "127.0.0.1")
    port = int(os.environ.get("MIROFISH_GRAPH_PROVIDER_PORT", "4891"))
    ThreadingHTTPServer((address, port), Handler).serve_forever()
